effect.shader:
float hash1(float x) {
    return fract(sin(x * 127.1 + float(seed) * 13.7) * 43758.5453);
}

/** Luminância ITU-R BT.709. */
float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

/** Sobel: magnitude do gradiente da luma. */
float sobelAqui(vec2 uv) {
    vec2 px = 1.0 / vec2(textureSize(inputImg, 0));
    float tl = luma(texture(inputImg, uv + vec2(-px.x,  px.y)).rgb);
    float t  = luma(texture(inputImg, uv + vec2( 0.0,   px.y)).rgb);
    float tr = luma(texture(inputImg, uv + vec2( px.x,  px.y)).rgb);
    float l  = luma(texture(inputImg, uv + vec2(-px.x,  0.0 )).rgb);
    float r  = luma(texture(inputImg, uv + vec2( px.x,  0.0 )).rgb);
    float bl = luma(texture(inputImg, uv + vec2(-px.x, -px.y)).rgb);
    float b  = luma(texture(inputImg, uv + vec2( 0.0,  -px.y)).rgb);
    float br = luma(texture(inputImg, uv + vec2( px.x, -px.y)).rgb);
    float gx = -tl - 2.0 * l - bl + tr + 2.0 * r + br;
    float gy = -tl - 2.0 * t - tr + bl + 2.0 * b + br;
    return length(vec2(gx, gy));
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    // Monocromatiza o original pela luma e tinge na cor do holograma.
    float L = luma(original.rgb);
    vec3 monocromado = hologramColor.rgb * L;

    // 1. Scanlines: linhas finas horizontais pela densidade.
    float scanline = 0.5 + 0.5 * sin(acScreenNorm.y * scanlineDensity);
    scanline = mix(1.0, scanline, scanlineStrength);
    monocromado *= scanline;

    // 2. Flicker: brilho global oscila.
    float quadro = floor(acTime * 15.0);
    float pisca = 1.0 + (hash1(quadro) - 0.5) * flickerStrength * 2.0;
    monocromado *= pisca;

    // 3. Interferência: faixas horizontais largas correndo.
    float faixa = sin(acScreenNorm.y * 8.0 - acTime * interferenceSpeed * 6.0);
    float peso = smoothstep(0.7, 1.0, faixa);
    monocromado *= mix(1.0, 1.4, peso);

    // 4. Borda viva: Sobel acrescenta brilho na silhueta.
    float borda = sobelAqui(acScreenNorm) * edgeStrength;
    monocromado += hologramColor.rgb * borda;

    // Fundo: o original escurecido (darken); soma com o holograma por cima.
    vec3 fundo = mix(original.rgb, vec3(0.0), darken);
    vec3 cor = fundo + monocromado * hologramColor.a;
    cor = clamp(cor, 0.0, 1.0);

    fragColor = vec4(cor, original.a);
}
